import json

from taf.sbts.oam.coam.admin import admin

from taf.rfrl.procedures.resources.python.connections import get_default_admin_connection_alias
from taf.rfrl.procedures.resources.python.delta_configurator.exceptions import EmptyDeltaFileFound
from taf.rfrl.procedures.resources.python.logger import log_input_and_output


class DeltaOperator:
    """
    Responsible for creating delta for recommissioning dynamically and performing it via admin API.
    DeltaOperator is able to create delta, save it to json or perform full delta recommissioning.
     """

    def __init__(self, bts_type='GNB', use_proxy=False):
        self._admin = admin()
        self._delta_id = 'hwpta_delta'
        self._connection_alias = get_default_admin_connection_alias(bts_type=bts_type, use_proxy=use_proxy)

        self._admin.create_delta(delta_id=self._delta_id)

    def perform_delta_recommissioning(self, skip_parameter_relation_errors=False, should_activate=True, timeout=60):
        """
        Performs delta recommissioning via admin api with stored delta variable under admin instance.
        :param skip_parameter_relation_errors: Skip parameter relation errors.
        :type skip_parameter_relation_errors: boolean
        :param should_activate: Should automatically activate plan.
        :type should_activate: boolean
        :param timeout: time in seconds to wait for successful recommissioning
        :type timeout: int
        """
        self._admin.perform_delta_recommissioning(delta_file=self.get_delta(),
                                                  skip_parameter_relation_errors=skip_parameter_relation_errors,
                                                  should_activate=should_activate,
                                                  timeout=int(timeout),
                                                  connection=self._connection_alias)

    def perform_delta_recommissioning_in_separate_process(self, skip_parameter_relation_errors=False,
                                                          should_activate=True, timeout=60):
        """
        Performs delta recommissioning via admin api with stored delta variable under admin instance in separate
        process.
        param skip_parameter_relation_errors: Skip parameter relation errors.
        :type skip_parameter_relation_errors: boolean
        :param should_activate: Should automatically activate plan.
        :type should_activate: boolean
        :param timeout: time in seconds to wait for successful recommissioning
        :type timeout: int
        """

        self._admin.connect_to(name="perform_delta_recommissioning")
        task = self._admin.run_keyword_in_background("perform_delta_recommissioning",
                                                     delta_file=self.get_delta(),
                                                     skip_parameter_relation_errors=skip_parameter_relation_errors,
                                                     should_activate=should_activate,
                                                     timeout=int(timeout),
                                                     connection="perform_delta_recommissioning")

        return task

    def add_moc_to_delta(self, dist_name):
        """
        Adds whole Managed Object to delta variable stored under admin instance.
        :param dist_name: full dist name to managed object that should be added.
        :type dist_name: str
        """
        self._admin.append_managed_object_to_delta(dist_name=dist_name, operation='create', delta_id=self._delta_id)

    def add_moc_removal_to_delta(self, dist_name):
        """
        Adds Managed Object removal plan to delta variable stored under admin instance.
        :param dist_name: full dist name to Managed Object that should be removed.
        :type dist_name: str
        """
        self._admin.append_managed_object_to_delta(dist_name=dist_name, operation='delete', delta_id=self._delta_id)

    def add_parameter_to_delta(self, dist_name, parameter, value):
        """
        Adds parameter to delta variable stored under admin instance.
        :param dist_name: full dist name to Managed Object where parameter should be added.
        :type dist_name: str
        :param parameter: parameter name that should be added e.g. 'pMax'
        :type parameter: str
        :param value: value of parameter that should be added e.g. '370'
        :type value: str or list[str]
        """
        self._admin.append_parameter_update_to_delta(dist_name=dist_name, parameter=parameter, value=value,
                                                     delta_id=self._delta_id)

    def add_parameters_to_delta(self, dist_name, delta_dict):
        """
        Adds parameters iteratively to delta variable stored under admin instance.
        :param dist_name: full dist name to Managed Object where parameters should be added.
        :type dist_name: str
        :param delta_dict: dictionary with parameters as keys and parameter values as key values that should be added,
                           e.g. {'pMax': '370', 'chbw': '30 MHz'}.
        :type delta_dict: dict
        """
        for param, param_value in delta_dict.items():
            self.add_parameter_to_delta(dist_name, parameter=param, value=param_value)

    def add_parameters_list_to_delta(self, dist_name, list_name, delta_dict):
        """
        Adds list parameters to delta variable stored under admin instance.
        :param dist_name: full dist name to Managed Object where list parameters should be added.
        :type dist_name: str
        :param list_name: name of list parameter that parameters should be added e.g. 'nrBandRfTestThresholds'.
        :type list_name: str
        :param delta_dict: dictionary with parameters as keys and parameter values as key values that should be added.
                           e.g. {"bandClass": "1", "totalRFPowerHighThreshold": "1200"}.
        :type delta_dict: dict
        """
        self._admin.append_parameter_update_to_delta(dist_name=dist_name, parameter=list_name, value=[delta_dict],
                                                     delta_id=self._delta_id)

    def reload_delta(self):
        """ Reloads delta variable stored under admin instance. """
        self._admin.remove_delta(delta_id=self._delta_id)
        self._admin.create_delta(delta_id=self._delta_id)

    def save_delta(self, output_path='/tmp/delta.json'):
        """
        Saves delta variable stored under admin instance to json file with provided output path.
        :param output_path: full path with file name and extension (json file) where delta should be saved,
                            delta.json in /tmp/ location at default.
        :type output_path: str
        """
        self._admin.save_delta(target_file_name=output_path, delta_id=self._delta_id)

    def remove_delta(self):
        """ Removes delta variable stored under admin instance. """
        self._admin.remove_delta(delta_id=self._delta_id)

    def get_delta(self):
        """
        Gets delta variable stored under admin instance.
        :returns: delta variable stored under admin instance.
        :rtype: str
        :raises EmptyDeltaFileFound when delta variable is empty.
        """
        res = self._admin.get_delta(delta_id=self._delta_id)

        if not res:
            raise EmptyDeltaFileFound("Your delta is empty! Please consider adding some MOCs or parameters, delta"
                                      " recommissioning with empty file is not a wise idea.")

        return res

    def add_structure_list_to_delta(self, dist_name, list_name, **kwargs):
        """
        Adds structure list to delta variable stored under admin instance.
        :param dist_name: full dist name to Managed Object where structure list should be added.
        :type dist_name: str
        :param list_name: name of structure list that should be added e.g. 'ulMuMimoFoThreshold'.
        :type list_name: str
        :param kwargs: dictionary with parameters names as keys and parameters values as key values that should be
                       added, e.g. {"foThresh256Qam": "300", "foThreshNon256Qam": "600"}.
        :type kwargs: dict
        """
        self._admin.append_complex_item_to_delta(dist_name=dist_name, list_name=list_name, delta_id=self._delta_id,
                                                 **kwargs)

    @log_input_and_output
    def load_delta_and_inject_changes(self, delta, not_updatable_params=None, object_already_existing=None,
                                      not_updatable_objects=None):
        """
        Loads delta from json file and injects changes to delta variable stored under admin instance.
        :param delta: full path with file name and extension (json file) where delta should be loaded from.
        :type delta: str
        :param not_updatable_params: list of parameters that cannot be updated online, e.g. ['nrBtsId', 'mrbtsId'],
                                     defaults to None, which means that no parameters will be skipped.
        :type not_updatable_params: list[str] or set[str] or tuple[str] or None
        :param object_already_existing: list of objects that already exist in BTS configuration,
                                        e.g. ['MRBTS-1/LNBTS-1/LNCEL-1', 'MRBTS-50146/MNL-1/MNLENT-1/CELLMAPPING-1']
                                        defaults to None, which means that no objects will be skipped.
        :type object_already_existing: list[str] or set[str] or tuple[str] or None
        :param not_updatable_objects: list of objects that cannot be updated online,
                                      e.g. ['MRBTS-50579/MNL-1/MNLENT-1/FMCADM-1/ALARMSUPP-1'],
                                      defaults to None, which means that no objects will be skipped.
        :type not_updatable_objects: list[str] or set[str] or tuple[str] or None
        """
        not_updatable_params = set() if not not_updatable_params else set(not_updatable_params)
        object_already_existing = set() if not object_already_existing else set(object_already_existing)
        not_updatable_objects = set() if not not_updatable_objects else set(not_updatable_objects)

        with open(delta) as delta_file:
            delta_data = json.load(delta_file)

        for operation, delta_objects in delta_data.items():
            for delta_object in delta_objects:
                if not (delta_object["dist_name"] in not_updatable_objects):
                    if operation == "removed":
                        self.add_moc_removal_to_delta(dist_name=delta_object["dist_name"])

                    elif operation == "added":
                        self._inject_new_objects_and_parameters(delta_object=delta_object,
                                                                object_already_existing=object_already_existing)

                    elif operation == "changed":
                        self._inject_changes_to_parameters(delta_object=delta_object,
                                                           not_updatable_params=not_updatable_params)

    def _inject_new_objects_and_parameters(self, delta_object, object_already_existing):

        if not delta_object["dist_name"] in object_already_existing:
            self.add_moc_to_delta(dist_name=delta_object["dist_name"])

        self._inject_changes_to_parameters(delta_object=delta_object, not_updatable_params=set())

    def _inject_changes_to_parameters(self, delta_object, not_updatable_params):
        for parameter in delta_object["params"]:
            if not (parameter["name"] in not_updatable_params):
                self.add_parameter_to_delta(
                    dist_name=delta_object["dist_name"], parameter=parameter["name"],
                    value=parameter["value"]
                )

        for list_parameter in delta_object["lists"]:
            if not (list_parameter["name"] in not_updatable_params):
                if list_parameter["params"]:
                    self.add_parameter_to_delta(
                        dist_name=delta_object["dist_name"],
                        parameter=list_parameter["name"],
                        value=[param["value"] for param in list_parameter["params"]
                               if not (param["name"] in not_updatable_params)]
                    )

                for item in list_parameter["items"]:
                    self.add_structure_list_to_delta(
                        dist_name=delta_object["dist_name"],
                        list_name=list_parameter["name"],
                        **{param["name"]: param["value"] for param in item["params"]
                           if not (param["name"] in not_updatable_params)}
                    )
